import React from 'react';
import { Route, Routes, Link } from 'react-router-dom';
import About from './About';
import Quiz from './Quiz';
import Kontakt from './Kontakt';
import './index.css';  // Falls du spezifische Stile für App.js hast

function Home() {
  return (
    <main>
      <section>
        <h2>Was erwartet Sie?</h2>
        <p>Es erwartet Sie ein kleines About-Me und ein Quiz.</p>
      </section>
    </main>
  );
}

function App() {
  return (
    <div className="App">
      <header>
        <h1>Willkommen auf meiner Webseite!</h1>
      </header>
      <div className="box">
        <nav>
          <ul>
            <li><Link to="/">Home</Link></li>
            <li><Link to="/about">About</Link></li>
            <li><Link to="/quiz">Quiz</Link></li>
            <li><Link to="/kontakt">
              <button id="contactButton">Kontaktieren Sie mich</button>
            </Link></li>
          </ul>
        </nav>
      </div>
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/about" element={<About />} />
        <Route path="/quiz" element={<Quiz />} />
        <Route path="/kontakt" element={<Kontakt />} />
      </Routes>
      <footer>
        <p>Copyright © 2024 Alle Rechte vorbehalten.</p>
      </footer>
    </div>
  );
}

export default App;
